local config = {
  ui_story_5085_50850100_1_dialog_content = "Urgh, my head...",
  ui_story_5085_50850100_2_dialog_content = "It feels like... I swallowed a bunch of seawater...",
  ui_story_5085_50850100_3_dialog_content = "<color=#e8d9bb>Fwoosh, Fwoosh—</color>",
  ui_story_5085_50850100_4_dialog_content = "Ugh, I'm so sick of the sound of waves... Wait, am I really at the beach?",
  ui_story_5085_50850100_5_dialog_content = "Oh... Are you finally awake? How are you feeling?",
  ui_story_5085_50850100_6_dialog_content = "Vice...?",
  ui_story_5085_50850100_7_dialog_content = "The sun is so bright... Where are we?",
  ui_story_5085_50850100_8_dialog_content = "Ah! You're awake!",
  ui_story_5085_50850100_9_dialog_content = "My potions seem to be working after all!",
  ui_story_5085_50850100_10_dialog_content = "Huh...? Y-You're not Vice!",
  ui_story_5085_50850100_11_dialog_content = "Sorry, I thought you were someone else! No wait... I should be thanking you for saving my life...",
  ui_story_5085_50850100_12_dialog_content = "Calm down, I was just doing what I could to help.",
  ui_story_5085_50850100_13_dialog_content = "You're the first person I've met in this <color=#FFB400>new world</color>, you know!",
  ui_story_5085_50850100_14_dialog_content = "Judging from your situation, it doesn't look like we're in the world of the Oren anymore. This could be trouble...",
  ui_story_5085_50850100_15_dialog_content = "What's the Oren? Wait... Did you say \"new world\"?!",
  ui_story_5085_50850100_16_dialog_content = "That's right!",
  ui_story_5085_50850100_17_dialog_content = "My friends and I were researching ways to travel to the Underworld...",
  ui_story_5085_50850100_18_dialog_content = "But then something went wrong with the portal, and we ended up in here!",
  ui_story_5085_50850100_19_dialog_content = "Even with all of my adventuring experience, I have no idea how to proceed! So, friend—",
  ui_story_5085_50850100_20_dialog_content = "Would you mind introducing this world to me?",
  ui_story_5085_50850100_21_dialog_content = "Introduce... the world...?",
  ui_story_5085_50850100_22_dialog_content = "<color=#e8d9bb>Caw—Caw—</color>",
  ui_story_5085_50850100_23_dialog_content = "... And that's more or less the story of Astra.",
  ui_story_5085_50850100_24_dialog_content = "But I don't think we're on the mainland anymore. If anything, this looks like an island off the coast of Astra.",
  ui_story_5085_50850100_25_dialog_content = "PlayerName! Courier Union just sent us the latest news on some ruins they found on an island!",
  ui_story_5085_50850100_26_dialog_content = "Oh? You mean the island ruins that everyone's been talking about lately?",
  ui_story_5085_50850100_27_dialog_content = "That's right! Apparently, they belong to an ancient Aurorian kingdom that rarely appears in historical records.",
  ui_story_5085_50850100_28_dialog_content = "Some scholars think that this kingdom can fill the gap that appeared after the Aurorians left Northland!",
  ui_story_5085_50850100_29_dialog_content = "Lumopolis and Umbraton are already getting ready to investigate the island, and they're offering massive commissions for anyone who helps with their explorations!",
  ui_story_5085_50850100_30_dialog_content = "D-Did you say \"massive commissions\"?!",
  ui_story_5085_50850100_31_dialog_content = "We... We're not too late to sign up, are we?!",
  ui_story_5085_50850100_32_dialog_content = "Heehee, I knew you'd be interested!",
  ui_story_5085_50850100_33_dialog_content = "And don't worry about travel expenses. I already talked to a few who are also going that way.",
  ui_story_5085_50850100_34_dialog_content = "Everyone's agreed to meet up and go together to cut down on travel costs!",
  ui_story_5085_50850100_35_dialog_content = "I just need you to double-check with them about the trip details before we leave.",
  ui_story_5085_50850100_36_dialog_content = "You're very thorough... Alright, I'll go make the final check now!",
  ui_story_5085_50850100_37_dialog_content = "PlayerName! I wanna go to the island and look for music from the ancient kingdom!",
  ui_story_5085_50850100_38_dialog_content = "I'm sure it'll make my Rediesel performances burn hotter than ever before! You just have to take me along!",
  ui_story_5085_50850100_39_dialog_content = "Sure, no problem!",
  ui_story_5085_50850100_40_dialog_content = "There are rumors of ancient mechas in the ruins. My curiosity was getting the better of me. I had to see for myself.",
  ui_story_5085_50850100_41_dialog_content = "Please, PlayerName!",
  ui_story_5085_50850100_42_dialog_content = "No objections here!",
  ui_story_5085_50850100_43_dialog_content = "L-Let's make one thing clear! I'm not going because I want to spend some time on the beach this summer...",
  ui_story_5085_50850100_44_dialog_content = "I just saw how hard Vice was working to prepare for this trip... I don't want her to overdo things, so I figured I should tag along.",
  ui_story_5085_50850100_45_dialog_content = "Of course, much appreciated, Zarya!",
  ui_story_5085_50850100_46_dialog_content = "<color=#e8d9bb>With a team of five now chosen, the party departs for an exciting island adventure...</color>",
  ui_story_5085_50850100_47_dialog_content = "Everyone here? Good! Now let's get going towards our destination—",
  ui_story_5085_50850100_48_dialog_content = "To the island ruins!",
  ui_story_5085_50850100_49_dialog_content = "I hope we discover some ancient music instruments!",
  ui_story_5085_50850100_50_dialog_content = "Or some legendary ancient mechas!",
  ui_story_5085_50850100_51_dialog_content = "This island sure holds many mysteries.",
  ui_story_5085_50850100_52_dialog_content = "(Vice and the others... they all seem a little too optimistic about this trip.)",
  ui_story_5085_50850100_53_dialog_content = "(People usually come back from these kinds of adventures empty-handed... But maybe I'm just being too negative.)",
  ui_story_5085_50850100_54_dialog_content = "PlayerName, Mr. Corax is calling!",
  ui_story_5085_50850100_55_dialog_content = "I hear you're en route to the island ruins. Is that right?",
  ui_story_5085_50850100_56_dialog_content = "I really wanted you to join me on this expedition, and search for any lost Aurorian medical knowledge, but it appears I was too late.",
  ui_story_5085_50850100_57_dialog_content = "Even you too?!",
  ui_story_5085_50850100_58_dialog_content = "Sorry... A lot of people have been asking for similar reasons.",
  ui_story_5085_50850100_59_dialog_content = "Exploring ruins is never a simple affair. Hopefully, the team you've put together includes capable fighters and medics.",
  ui_story_5085_50850100_60_dialog_content = "From what I've heard, extreme weather alone has defeated many exploratory teams. I worry for your sake.",
  ui_story_5085_50850100_61_dialog_content = "I think we'll be fine...",
  ui_story_5085_50850100_62_dialog_content = "The sea has been calm this entire time...",
  ui_story_5085_50850100_63_dialog_content = "What's this?! Lightning... on a clear day?!",
  ui_story_5085_50850100_64_dialog_content = "Ahhhh—It's raining fire! Take cover, everyone!",
  ui_story_5085_50850100_65_dialog_content = "Th-The ship's not going to capsize, is it?!",
  ui_story_5085_50850100_66_dialog_content = "Hold on, everyone!",
  ui_story_5085_50850100_67_dialog_content = "<size=50><color=#e8d9bb>Boom—!</color></size>",
  ui_story_5085_50850100_68_dialog_content = "<color=#e8d9bb>The ship is splintering apart, and the crew is clinging desperately to the wreckage, tossed about by the merciless waves.</color>",
  ui_story_5085_50850100_69_dialog_content = "<color=#e8d9bb>Adrift on the currents, I found myself here before I knew it...</color>",
  ui_story_5085_50850100_70_dialog_content = "So... I'm not very familiar with this place either. I'm sorry.",
  ui_story_5085_50850100_71_dialog_content = "I'm not entirely sure I can help you in any way, either...",
  ui_story_5085_50850100_72_dialog_content = "I see. That's alright!",
  ui_story_5085_50850100_73_dialog_content = "Thanks for the intel! Now I feel like I've got a pretty good read on this situation.",
  ui_story_5085_50850100_74_dialog_content = "When it comes to places like islands and ruins, I've got tons of experience!",
  ui_story_5085_50850100_75_dialog_content = "That's a relief! Before we came here, I had a good idea of what to expect.",
  ui_story_5085_50850100_76_dialog_content = "Just wondering where the others ended up. They must have washed up on shore too, right?",
  ui_story_5085_50850100_77_dialog_content = "Your friends... Oh, that reminds me!",
  ui_story_5085_50850100_78_dialog_content = "Klaudia and Patty got sent to this world as well, but I haven't been able to find either of them...",
  ui_story_5085_50850100_79_dialog_content = "But something tells me they're definitely on this island!",
  ui_story_5085_50850100_80_dialog_content = "And if you'll pardon the expression, it looks like you and I are in the same boat here.",
  ui_story_5085_50850100_81_dialog_content = "Haha, you can say that again...",
  ui_story_5085_50850100_82_dialog_content = "And since that's the case... Why don't we try looking for our friends together?",
  ui_story_5085_50850100_83_dialog_content = "We'll be a lot more effective if we work as a team!",
  ui_story_5085_50850100_84_dialog_content = "Really?! Oh, thanks so much for your help! You know, you seem pretty worried about your friends too. You kept calling out \"Vice\" when you were unconscious earlier...",
  ui_story_5085_50850100_85_dialog_content = "She must be your closest friend, huh?",
  ui_story_5085_50850100_86_dialog_content = "I-Is that what you think?!",
  ui_story_5085_50850100_87_dialog_content = "... Maybe you're right. Coming here was her idea, and I didn't even hesitate to join her.",
  ui_story_5085_50850100_88_dialog_content = "Oh, I see! She must love adventures. I'm even more excited to meet her now!",
  ui_story_5085_50850100_89_dialog_content = "Can you walk? You can lean on me if you're hurt.",
  ui_story_5085_50850100_90_dialog_content = "Thanks, but I think I can manage.",
  ui_story_5085_50850100_91_dialog_content = "Good! Then, allow me to formally introduce myself—",
  ui_story_5085_50850100_92_dialog_content = "My name is Reisalin Stout, but you can just call me Ryza!",
  ui_story_5085_50850100_93_dialog_content = "Nice to meet you, Ryza. My name's PlayerName, but most people just call me the Navigator.",
  ui_story_5085_50850100_94_dialog_content = "Sounds good! Looking forward to working with you, Navigator!",
  ui_story_5085_50850100_95_dialog_content = "Now let's get going!",
  ui_story_5085_50850201_1_dialog_content = "Phew... This looks pretty useful.",
  ui_story_5085_50850201_2_dialog_content = "Wow, this flower is beautiful! I wonder if I can use it as a substitute for Health Flowers.",
  ui_story_5085_50850201_3_dialog_content = "Think this rock has any uses? I should bring it along, just to be safe...",
  ui_story_5085_50850201_4_dialog_content = "Uh, it looks like your pack is pretty full already.",
  ui_story_5085_50850201_5_dialog_content = "Ah! You're right, I must've gotten a little carried away with my gathering...",
  ui_story_5085_50850201_6_dialog_content = "You seem pretty fond of plants, especially... grass roots?",
  ui_story_5085_50850201_7_dialog_content = "Eheheh... Not exactly. I just want to try using these as <color=#FFB400>alchemy</color> materials!",
  ui_story_5085_50850201_8_dialog_content = "A-Alchemy?!",
  ui_story_5085_50850201_9_dialog_content = "Huh? Does alchemy not exist in this world or something?",
  ui_story_5085_50850201_10_dialog_content = "Emmm, as far as the world is concerned, it's more of a lost art from the ancient past.",
  ui_story_5085_50850201_11_dialog_content = "So, it actually exists in your world?",
  ui_story_5085_50850201_12_dialog_content = "That's right! And don't underestimate me, I'm actually a fairly accomplished <color=#FFB400>alchemist</color>.",
  ui_story_5085_50850201_13_dialog_content = "I can use all kinds of regular objects as materials and <color=#FFB400>synthesize</color> them into medicine and other useful items!",
  ui_story_5085_50850201_14_dialog_content = "Really? That's impressive!",
  ui_story_5085_50850201_15_dialog_content = "If only I had a nice, big alchemy cauldron... Then I could show you what I can really do!",
  ui_story_5085_50850201_16_dialog_content = "A cauldron, huh? I'm not sure we'll find something like that on a deserted island... But maybe the ruins have something you can use?",
  ui_story_5085_50850201_17_dialog_content = "In any case, let's keep moving. We might even find better things up ahead.",
  ui_story_5085_50850201_18_dialog_content = "Now you're speaking my language!",
  ui_story_5085_50850201_19_dialog_content = "Let me just lighten my load a little first.",
  ui_story_5085_50850201_20_dialog_content = "I can help you carry some stuff too. After all, I doubt we'll be leaving this island anytime soon.",
  ui_story_5085_50850201_21_dialog_content = "If we're going to be stuck here for a few days, I'm sure your alchemy will definitely come in handy!",
  ui_story_5085_50850201_22_dialog_content = "You have a point!",
  ui_story_5085_50850201_23_dialog_content = "Then we'll start by finding our friends, then we'll look for the cauldron...",
  ui_story_5085_50850201_24_dialog_content = "Graah—",
  ui_story_5085_50850201_25_dialog_content = "Ah! I-It's a monster!",
  ui_story_5085_50850201_26_dialog_content = "Are all the monsters in your world this scary-looking?!",
  ui_story_5085_50850201_27_dialog_content = "There are Eclipsites even on a remote island like this?!",
  ui_story_5085_50850201_28_dialog_content = "This is bad... without Aurorians around...",
  ui_story_5085_50850201_29_dialog_content = "Eclipsites? Is that what you call these things?",
  ui_story_5085_50850201_30_dialog_content = "That one looks like it's carrying something in its claws...",
  ui_story_5085_50850201_31_dialog_content = "Wait a minute, isn't that...",
  ui_story_5085_50850201_32_dialog_content = "Vice's pack?!",
  ui_story_5085_50850201_33_dialog_content = "<color=#e8d9bb>Whack!</color>",
  ui_story_5085_50850201_34_dialog_content = "You rotten Eclipsite! Give me back my... Ah! PlayerName!",
  ui_story_5085_50850201_35_dialog_content = "Perfect timing! Our supplies are still in that pack! We'll be in trouble if we don't take it back!",
  ui_story_5085_50850201_36_dialog_content = "Give me a hand!",
  ui_story_5085_50850201_37_dialog_content = "Roger!",
  ui_story_5085_50850202_1_dialog_content = "Phew, that takes care of that!",
  ui_story_5085_50850202_2_dialog_content = "We would've had to survive like cavepeople without these supplies.",
  ui_story_5085_50850202_3_dialog_content = "I'm so glad I found you, PlayerName! But uh, who is this...?",
  ui_story_5085_50850202_4_dialog_content = "Ah, you must be Vice! The Navigator told me about you when we first met. My name is Ryza!",
  ui_story_5085_50850202_5_dialog_content = "Eh—Yes, my name is Vice; nice to meet you, Miss Ryza! Um... Are you also an adventurer exploring the island?",
  ui_story_5085_50850202_6_dialog_content = "Kind of... To be more specific, she's an alchemist who came here from another world.",
  ui_story_5085_50850202_7_dialog_content = "An alchemist... from another world?",
  ui_story_5085_50850202_8_option_content = "Explain the situation to Vice",
  ui_story_5085_50850202_9_dialog_content = "<color=#e8d9bb>I give Vice a quick rundown of how Ryza and I met.</color>",
  ui_story_5085_50850202_10_dialog_content = "So that's what happened, huh?",
  ui_story_5085_50850202_11_dialog_content = "Yep! He kept calling your name when he was still unconscious too!",
  ui_story_5085_50850202_12_dialog_content = "I see...",
  ui_story_5085_50850202_13_dialog_content = "A-Ahem... I think we should move on to something more important, like our current situation.",
  ui_story_5085_50850202_14_dialog_content = "I agree.",
  ui_story_5085_50850202_15_dialog_content = "When I was chasing that Eclipsite, I realized there were many more Eclipsites on this island than I thought.",
  ui_story_5085_50850202_16_dialog_content = "Resources are especially scarce too. If we can't find a way to replenish our supplies...",
  ui_story_5085_50850202_17_dialog_content = "Just a second, Vice! You're hurt, aren't you?",
  ui_story_5085_50850202_18_dialog_content = "If you don't mind, try applying some of this medicine to your wound. I made it using alchemy.",
  ui_story_5085_50850202_19_dialog_content = "Huh? That's okay, it's just a scratch... I'd rather not waste your precious medicine on something like this...",
  ui_story_5085_50850202_20_dialog_content = "It's okay, really—",
  ui_story_5085_50850202_21_dialog_content = "<color=#e8d9bb>Ryza gently spread some of her medicine on Vice's wound—</color>",
  ui_story_5085_50850202_22_dialog_content = "Nngh... Huh?!",
  ui_story_5085_50850202_23_dialog_content = "It's completely healed... Is this the power of your alchemy, Ryza?",
  ui_story_5085_50850202_24_dialog_content = "You must be able to do anything with it!",
  ui_story_5085_50850202_25_dialog_content = "That's right! Alchemy can solve just about any problem! Or at least I like to think so... But I know for sure that it'll make a living on this remote island a lot easier! It might even come in handy against Eclipsites!",
  ui_story_5085_50850202_26_dialog_content = "I'm sure it can! I believe in your strength.",
  ui_story_5085_50850202_27_dialog_content = "I bet Vice sees it too! You'd be the perfect teammate for exploring ancient ruins and secret territories.",
  ui_story_5085_50850202_28_dialog_content = "I agree! Nothing's better than crossing paths with a powerful ally like you.",
  ui_story_5085_50850202_29_dialog_content = "Haha, guess I'd better work hard for everyone's sake too! And I'll start by finding the cauldron.",
  ui_story_5085_50850202_30_dialog_content = "A cauldron?",
  ui_story_5085_50850202_31_dialog_content = "It's what Ryza needs to perform alchemy and create all sorts of items. Anything that resembles a pot will do.",
  ui_story_5085_50850202_32_dialog_content = "Ah, got it.",
  ui_story_5085_50850202_33_dialog_content = "I saw something like that on my way here. It looked like some kind of ceremonial vessel in the ruins...",
  ui_story_5085_50850202_34_dialog_content = "<color=#e8d9bb>The sound of a flute suddenly comes from deep within the forest—</color>",
  ui_story_5085_50850202_35_dialog_content = "I think there's someone in the forest!",
  ui_story_5085_50850202_36_dialog_content = "That instrument... It must be Klaudia!",
  ui_story_5085_50850202_37_dialog_content = "Please come with me! She's my most trustworthy companion... As well as my best friend!",
  ui_story_5085_50850301_1_dialog_content = "Come, my friend from a distant land! Let us defeat the Eclipsites at hand!♪",
  ui_story_5085_50850301_2_dialog_content = "Ah, it's PlayerName!",
  ui_story_5085_50850301_3_dialog_content = "Thank goodness you're still alive!",
  ui_story_5085_50850301_4_dialog_content = "Sorry, but I don't go down that easily!",
  ui_story_5085_50850301_5_dialog_content = "Klaudia!",
  ui_story_5085_50850301_6_dialog_content = "Ah, Ryza!",
  ui_story_5085_50850301_7_dialog_content = "Thank goodness... When everyone got separated in the portal, I didn't know what to do...",
  ui_story_5085_50850301_8_dialog_content = "Sorry for making you worry, Klaudia.",
  ui_story_5085_50850301_9_dialog_content = "But if I was able to find you here, that means Patty is most likely somewhere on the island too.",
  ui_story_5085_50850301_10_dialog_content = "Yes, I think so as well.",
  ui_story_5085_50850301_11_dialog_content = "I knew you would find me eventually, so I decided to stay here and guard this for you, Ryza.",
  ui_story_5085_50850301_12_dialog_content = "It's...",
  ui_story_5085_50850301_13_dialog_content = "A barrel!",
  ui_story_5085_50850301_14_dialog_content = "Uh, no... I meant the thing next to it.",
  ui_story_5085_50850301_15_dialog_content = "Oh! It's... It's a big, beautiful cauldron! Thank you so much, Klaudia!",
  ui_story_5085_50850301_16_dialog_content = "It appears to be a relic from an ancient civilization, but the size and shape are perfect for alchemy.",
  ui_story_5085_50850301_17_dialog_content = "It's the three-legged vessel I saw earlier! The ruins must be right around here somewhere.",
  ui_story_5085_50850301_18_dialog_content = "Ah, I forgot to introduce ourselves! My name's Vice, and this is PlayerName, our Navigator.",
  ui_story_5085_50850301_X18_dialog_content = "A pleasure to meet you, Miss Vice and Mr. Navigator. Miss Barbara actually told me about you on the way; I hope we can become good friends!",
  ui_story_5085_50850301_X19_dialog_content = "I'm sure you will! Now let's not squander all of Klaudia's hard work... PlayerName, could you please use your powers to sense this cauldron?",
  ui_story_5085_50850301_19_dialog_content = "I agree. We don't want anything to happen to Ryza once she starts using it.",
  ui_story_5085_50850301_20_dialog_content = "What's that? The great and powerful Navigator is finally going to use his mysterious abilities?",
  ui_story_5085_50850301_21_dialog_content = "It's nothing, just the usual extrasensory perception—",
  ui_story_5085_50850301_22_option_content = "Force Boost!",
  ui_story_5085_50850301_23_dialog_content = "...",
  ui_story_5085_50850301_24_dialog_content = "Well?",
  ui_story_5085_50850301_25_dialog_content = "I see a set of ruins... with lots of broken vessels lying on the ground...",
  ui_story_5085_50850301_26_dialog_content = "Seems they're part of the ruins after all.",
  ui_story_5085_50850301_27_dialog_content = "A small island kingdom built on the ancient civilization's technology, it prospered until...",
  ui_story_5085_50850301_28_dialog_content = "Come back. The kingdom needs you.",
  ui_story_5085_50850301_29_dialog_content = "Ah—",
  ui_story_5085_50850301_30_dialog_content = "What happened?",
  ui_story_5085_50850301_31_dialog_content = "You look like you've seen a ghost. Would you like some water?",
  ui_story_5085_50850301_32_dialog_content = "... It's nothing. I just saw the history of the ruins, and there was a lot to take in at one time...",
  ui_story_5085_50850301_33_dialog_content = "Anyway, no Darkflow contamination on the vessel, and the Eclipsites haven't even laid a finger on it. It should be safe to use.",
  ui_story_5085_50850301_34_dialog_content = "Really? Great, thanks a bunch! But still, I hope you're not overdoing this.",
  ui_story_5085_50850301_35_dialog_content = "I'm fine, honestly. Besides, I'm really looking forward to seeing how your powers will improve our deserted island life!",
  ui_story_5085_50850301_36_dialog_content = "No need to worry about that! With me around, survival is about to get a lot easier!",
  ui_story_5085_50850301_37_dialog_content = "But... There's still a very big obstacle to our survival lurking around...",
  ui_story_5085_50850301_38_dialog_content = "Those evil creatures are getting awfully restless. If it weren't for Miss Barbara's incredible fighting skills just now...",
  ui_story_5085_50850301_39_dialog_content = "Oh my, I'm not THAT strong, you know.",
  ui_story_5085_50850301_40_dialog_content = "Your support was the only reason our battle went so smoothly, my friend!",
  ui_story_5085_50850301_41_dialog_content = "And that flute... It was so captivating, even for a professional idol like myself!",
  ui_story_5085_50850301_42_dialog_content = "We need to take some precautions against Eclipsites. We should set up camp in a place that can be easily defended.",
  ui_story_5085_50850301_43_dialog_content = "This world of yours... Does it have any items or materials for repelling monsters? I mean, Eclipsites?",
  ui_story_5085_50850301_44_dialog_content = "Doubt it. Wish there was something that easy here.",
  ui_story_5085_50850301_45_dialog_content = "Um...",
  ui_story_5085_50850301_46_dialog_content = "What's the matter, Klaudia?",
  ui_story_5085_50850301_47_dialog_content = "Ryza, do you think... We'll be able to go home?",
  ui_story_5085_50850301_48_dialog_content = "Of course. We've always made it back from our adventures, haven't we?",
  ui_story_5085_50850301_50_dialog_content = "I know we've run into some troubles already, but right now I just want to enjoy my adventure with everyone here!",
  ui_story_5085_50850301_51_dialog_content = "Agreed! Nothing is more fun than going on adventures with you, Ryza!",
  ui_story_5085_50850301_53_dialog_content = "Heeheehee, thanks! Now then, for the sake of finding our way home safely, let's join Navigator and his friends and look for Patty!",
  ui_story_5085_50850301_58_dialog_content = "Just a moment! I think I hear something dreadful...",
  ui_story_5085_50850301_59_dialog_content = "Eclipsites! And they're getting closer!",
  ui_story_5085_50850301_60_dialog_content = "Graah—",
  ui_story_5085_50850301_61_dialog_content = "Look out, Ryza!",
  ui_story_5085_50850301_62_dialog_content = "Wow... Another battle?!",
  ui_story_5085_50850302_1_dialog_content = "Behold the power of alchemy!",
  ui_story_5085_50850302_2_dialog_content = "Graah...",
  ui_story_5085_50850302_3_dialog_content = "Phew... That was close! Good thing I had enough materials!",
  ui_story_5085_50850302_4_dialog_content = "Hey Ryza, did you make that using alchemy?",
  ui_story_5085_50850302_5_dialog_content = "That's right! Pretty impressive, huh?",
  ui_story_5085_50850302_6_dialog_content = "That's an understatement, to say the least. With this kind of power, exploring the island shouldn't be a challenge.",
  ui_story_5085_50850302_7_dialog_content = "However, that only solves our fighting concerns. Miss Vice was right: we need to find a suitable place to set up our base camp.",
  ui_story_5085_50850302_8_dialog_content = "Yeah, you're right. With this many Eclipsites roaming around, a safe place to strategize would be very helpful.",
  ui_story_5085_50850302_9_dialog_content = "So, does anyone have any suggestions for our camp?",
  ui_story_5085_50850302_10_dialog_content = "I think... Somewhere near the beach would be best.",
  ui_story_5085_50850302_11_dialog_content = "From what Miss Barbara and I saw earlier, much of this island appears to be littered with the broken remnants of ancient ruins.",
  ui_story_5085_50850302_12_dialog_content = "The same may be true of the Eclipsites...",
  ui_story_5085_50850302_13_dialog_content = "However, the beaches appear to be mostly clear of these remnants, which may mean they're our safest choice. Not only that, but we can also keep an eye out for passing ships.",
  ui_story_5085_50850302_14_dialog_content = "I was just thinking the exact same thing!",
  ui_story_5085_50850302_15_dialog_content = "Looks like you have a real eye for strategy.",
  ui_story_5085_50850302_16_dialog_content = "You and Ryza are totally different... Which is why you complement each other so well!",
  ui_story_5085_50850302_17_dialog_content = "Actually, Ryza has been watching over me all this time.",
  ui_story_5085_50850302_18_dialog_content = "What are you talking about? You're the one who's always taking care of me.",
  ui_story_5085_50850302_19_dialog_content = "Yes, yes, we get that you two are very close! Now let's move on to our next objective!",
  ui_story_5085_50850302_20_dialog_content = "And that would be—Building a beautiful stage to express our feelings of friendship!",
  ui_story_5085_50850302_21_dialog_content = "Er, I think she means finding a suitable beach for our camp.",
  ui_story_5085_50850302_22_dialog_content = "What are you doing, Klaudia? Did you drop something?",
  ui_story_5085_50850302_23_dialog_content = "Ah, I was just looking for those remnants I mentioned earlier. There appear to be a few of them lying around...",
  ui_story_5085_50850302_24_dialog_content = "Whenever Ryza takes us on an adventure, we tend to pick up seemingly-useless items like this.",
  ui_story_5085_50850302_25_dialog_content = "You never know... Some of them might be potent alchemy materials.",
  ui_story_5085_50850302_26_dialog_content = "I see. Maybe I can use my powers to look for something useful too!",
  ui_story_5085_50850302_27_dialog_content = "That sounds a lot like treasure-hunting! As a native of the Rediesel Desert, that happens to be one of my fortés!",
  ui_story_5085_50850302_28_dialog_content = "Hmm... This looks like the plaything of an ancient noble... Boring!",
  ui_story_5085_50850302_29_dialog_content = "Hahaha! I guess I should mention that folks from the Rediesel Desert don't care much for anything that can't be fitted onto a huge machine.",
  ui_story_5085_50850302_30_dialog_content = "Speaking of huge machines... Someone was looking for information on ancient mechas here on the island.",
  ui_story_5085_50850302_31_dialog_content = "That's odd... for some reason, I can't remember who it was.",
  ui_story_5085_50850302_32_dialog_content = "What kind of stuff are you talking about? Can I use alchemy on it?",
  ui_story_5085_50850302_33_dialog_content = "Ryza, watch your step!",
  ui_story_5085_50850302_34_dialog_content = "... Whoa!",
  ui_story_5085_50850302_35_dialog_content = "That was close... How come there's ice here?!",
  ui_story_5085_50850302_36_dialog_content = "Hey... If you look closely at it, the ice looks oddly arrow-shaped...",
  ui_story_5085_50850302_37_dialog_content = "Arrow-shaped ice? Hang on... Could it be?!",
  ui_story_5085_50850302_38_dialog_content = "This must be Zarya's doing!",
  ui_story_5085_50850302_39_dialog_content = "It looks like she was leaving a trail behind... I'm sure we'll find her if we follow it.",
  ui_story_5085_50850302_40_dialog_content = "So, Navigator's friend left us a sign!",
  ui_story_5085_50850302_41_dialog_content = "I wonder if Patty did the same somewhere else?",
  ui_story_5085_50850401_1_dialog_content = "The Eclipsites have been eradicated. Please leave another sign here, Miss Zarya.",
  ui_story_5085_50850401_2_dialog_content = "Uh... Sure!",
  ui_story_5085_50850401_3_dialog_content = "Is there a problem? You seem preoccupied.",
  ui_story_5085_50850401_4_dialog_content = "No, it's just... You're a lot more mature than your appear, Lady Patricia.",
  ui_story_5085_50850401_5_dialog_content = "Even though you don't fully approve of my plan, you've been helping me eliminate the Eclipsites and leave signs for the others...",
  ui_story_5085_50850401_6_dialog_content = "<size=30>If only I could be a little more mature, too...</size>",
  ui_story_5085_50850401_7_dialog_content = "Honestly, I told you already—",
  ui_story_5085_50850401_8_dialog_content = "This has nothing to do with maturity. A noble doesn't go back on her word easily, especially when she has agreed to do something.",
  ui_story_5085_50850401_9_dialog_content = "Also, you don't have to address me like that. You can just...",
  ui_story_5085_50850401_10_dialog_content = "Hey—",
  ui_story_5085_50850401_11_dialog_content = "Zarya—Over here—",
  ui_story_5085_50850401_12_dialog_content = "It's PlayerName!",
  ui_story_5085_50850401_13_dialog_content = "If someone's found us, then that means...",
  ui_story_5085_50850401_14_dialog_content = "The ice markers... They worked!",
  ui_story_5085_50850401_15_dialog_content = "Patty! We finally found you!",
  ui_story_5085_50850401_16_dialog_content = "Ryza?! Oh...",
  ui_story_5085_50850401_17_dialog_content = "I had a feeling you were on the island too! This is quite the crazy reunion, huh?",
  ui_story_5085_50850401_18_dialog_content = "Thank goodness you're safe, Patricia.",
  ui_story_5085_50850401_19_dialog_content = "I'm just glad we all found each other... So can I ask who your friends are?",
  ui_story_5085_50850401_20_dialog_content = "<color=#e8d9bb>After exchanging brief introductions, Patricia explains her previous situation.</color>",
  ui_story_5085_50850401_21_dialog_content = "I see. So you've been working with this Navigator ever since we were transported to this world.",
  ui_story_5085_50850401_22_dialog_content = "You always seem to attract other adventure-seekers wherever you go, Ryza. It's uncanny, really.",
  ui_story_5085_50850401_23_dialog_content = "It's not just me, you know. Our friends here happen to have similar goals as us!",
  ui_story_5085_50850401_24_dialog_content = "I understand now. Please allow me to introduce myself once more: I am Patricia Abelheim, but you may call me Patty for short. I am honored to meet you all.",
  ui_story_5085_50850401_25_dialog_content = "Wow, what an introduction... She sounds just like a knight!",
  ui_story_5085_50850401_26_dialog_content = "That's because Patty is a noble!",
  ui_story_5085_50850401_27_dialog_content = "I see, that explains why she reminds me of a certain friend! She's also a dignified noble, as well as an awesome knight!",
  ui_story_5085_50850401_28_dialog_content = "And with that, all of my friends are accounted for! What about you, Navigator?",
  ui_story_5085_50850401_29_dialog_content = "Let's see...",
  ui_story_5085_50850401_30_dialog_content = "With Zarya found, our party should be complete now too.",
  ui_story_5085_50850401_31_dialog_content = "Hmm... Maybe we should take one last head count, just to be sure?",
  ui_story_5085_50850401_32_dialog_content = "One, two, three, four! Yep, we're all here!",
  ui_story_5085_50850401_33_dialog_content = "Only four? I feel like we're missing someone...",
  ui_story_5085_50850401_34_dialog_content = "Maybe you're just thinking of Corax? He told you he wanted to come too, remember?",
  ui_story_5085_50850401_35_dialog_content = "You're right... Maybe I am overthinking things.",
  ui_story_5085_50850401_36_dialog_content = "I think we're good now, Ryza. What's your next move?",
  ui_story_5085_50850401_37_dialog_content = "First, I need to retrieve that cauldron and take it to a suitable beach. After that, I can create an atelier for us to use!",
  ui_story_5085_50850401_38_dialog_content = "Once we have that, we'll rest up, create tons of useful items, and move on with our exploration of the ruins!",
  ui_story_5085_50850401_39_dialog_content = "What does everyone think of the plan so far?",
  ui_story_5085_50850401_40_dialog_content = "Even though we're in a completely unknown world... Ryza is as motivated as ever.",
  ui_story_5085_50850401_41_dialog_content = "No objections here. I believe an Atelier will be essential for finding our way home.",
  ui_story_5085_50850401_42_dialog_content = "Agreed. The island ruins related to ancient music are also worthy of investigating.",
  ui_story_5085_50850401_43_dialog_content = "I believe Ryza's plan is a sound one.",
  ui_story_5085_50850401_44_dialog_content = "As do I.",
  ui_story_5085_50850401_45_dialog_content = "Great! I'd love to keep the flames of our summer adventure burning hot too! What about you, Navigator?",
  ui_story_5085_50850401_46_dialog_content = "We came to explore those ruins as well.",
  ui_story_5085_50850401_47_dialog_content = "But there's still the question of how we're going to return to the mainland...",
  ui_story_5085_50850401_48_dialog_content = "In any case, we can't afford to go back right now!",
  ui_story_5085_50850401_49_dialog_content = "If we go home empty-handed, we'll lose our payment AND we'll have to pay for the ship... Ugh, if I knew something like this was gonna happen, I would've bought disaster insurance back in Umbraton...",
  ui_story_5085_50850401_50_dialog_content = "Besides, maybe we'll find a ship or some sort of communication device in the ruins?",
  ui_story_5085_50850401_51_dialog_content = "... You're right. I can't think of a better solution right now anyway...",
  ui_story_5085_50850401_52_dialog_content = "In that case, let's join the exploration and complete our mission!",
  ui_story_5085_50850401_53_dialog_content = "Wow, it looks like everyone's in high spirits! Now then... We're off to the beach—",
  ui_story_5085_50850401_54_dialog_content = "Let's gooooo!",
  ui_story_5085_50850501_1_dialog_content = "Ha—Phew—!",
  ui_story_5085_50850501_2_dialog_content = "This place should do just fine! Thanks again, everyone!",
  ui_story_5085_50850501_3_dialog_content = "I never even considered using Zarya's ice this way. We actually transport the cauldron all the way here with the help of ice...",
  ui_story_5085_50850501_4_dialog_content = "I-It's nothing, really. My powers aren't good for much else than this...",
  ui_story_5085_50850501_5_dialog_content = "It feels like everything is gonna work out once Ryza is able to perform her alchemy.",
  ui_story_5085_50850501_6_dialog_content = "Heheh, that's right. Ryza's alchemy is something truly incredible.",
  ui_story_5085_50850501_7_dialog_content = "As for a suitable location for the atelier, take a look at this place, Ryza—",
  ui_story_5085_50850501_8_dialog_content = "This part of the forest provides ample sunlight and readily available clean water. It's a worthwhile place for setting up shelter.",
  ui_story_5085_50850501_9_dialog_content = "The beach is also nearby, which allows us to view the ocean at any time.",
  ui_story_5085_50850501_11_dialog_content = "I don't see why not! I'm sure everyone would appreciate a nice seaside cottage in the woods!",
  ui_story_5085_50850501_12_dialog_content = "I'm ready to begin synthesizing everything we need to construct our cottage.",
  ui_story_5085_50850501_13_dialog_content = "Then I'll go get Navigator. He's been wanting to see Ryza's alchemy for a long time now.",
  ui_story_5085_50850501_14_dialog_content = "Is that—?",
  ui_story_5085_50850501_15_dialog_content = "Wow! There's so much!!!",
  ui_story_5085_50850501_16_dialog_content = "All kinds of construction materials, cut and molded to exact specifications... And she just keeps pulling them out of the cauldron!",
  ui_story_5085_50850501_17_dialog_content = "All we did was throw in a bunch of random, ordinary stuff...",
  ui_story_5085_50850501_18_dialog_content = "S-So this is the power of alchemy! It's so useful! You could build a whole house without even breaking a sweat...",
  ui_story_5085_50850501_19_dialog_content = "Don't just stand there around while Miss Ryza does all the work, everyone! Let's get started building that atelier!",
  ui_story_5085_50850501_20_dialog_content = "I'm coming!",
  ui_story_5085_50850501_21_dialog_content = "I can handle moving all of the wood, so just leave it to me!",
  ui_story_5085_50850501_22_dialog_content = "Is that okay? They're awfully heavy...",
  ui_story_5085_50850501_23_dialog_content = "Maybe I should do it instead? Asking a petite idol to lug around wooden beams seems a little wrong.",
  ui_story_5085_50850501_24_dialog_content = "Is that so? Humph! Don't you dare underestimate the Rediesel Desert's number-one idol! Arrrrraaaaaagh—",
  ui_story_5085_50850501_25_dialog_content = "<color=#e8d9bb>Clang—Snap—Thud—!</color>",
  ui_story_5085_50850501_26_dialog_content = "I-Incredible! She was able to carry all of those construction materials despite her small physique...",
  ui_story_5085_50850501_27_dialog_content = "What are you doing, Zarya?",
  ui_story_5085_50850501_28_dialog_content = "Me? Er... I'm using my ice to create support structures for everyone and to cool the area off.",
  ui_story_5085_50850501_29_dialog_content = "It was Patty's idea.",
  ui_story_5085_50850501_30_dialog_content = "It's hard not to be impressed after seeing what you're capable of doing, Miss Zarya.",
  ui_story_5085_50850501_31_dialog_content = "Despite being the <color=#FFB400>same age</color> as me, your powers are far greater than mine... It's something truly incredible.",
  ui_story_5085_50850501_32_dialog_content = "...",
  ui_story_5085_50850501_33_dialog_content = "Er... Did I say something wrong?",
  ui_story_5085_50850501_34_dialog_content = "I don't know, did you?",
  ui_story_5085_50850501_35_dialog_content = "Uh, it might be because you mentioned her age...",
  ui_story_5085_50850501_36_dialog_content = "Miss Zarya's age? Are you telling me... She and I aren't actually that close in age?!",
  ui_story_5085_50850501_37_dialog_content = "Oh boy...",
  ui_story_5085_50850501_39_dialog_content = "...",
  ui_story_5085_50850501_40_dialog_content = "<size=30>I'm <color=#FFB400>117</color>...</size>",
  ui_story_5085_50850501_41_dialog_content = "<size=50>?!?!</size>",
  ui_story_5085_50850501_42_dialog_content = "She actually said it.",
  ui_story_5085_50850501_X42_dialog_content = "I hope that doesn't freak you guys out.",
  ui_story_5085_50850501_X43_dialog_content = "I won't lie, it's a little shocking. But when I think about it, we have a friend who looks nothing like their actual age too.",
  ui_story_5085_50850501_X44_dialog_content = "That's true.",
  ui_story_5085_50850501_X45_dialog_content = "Now that you mention it, you're right.",
  ui_story_5085_50850501_43_dialog_content = "Ahhhh—Let's just forget about it and move on! We still need to build this atelier!!!",
  ui_story_5085_50850501_44_dialog_content = "We're finally done, and the cauldron is exactly where it needs to be!",
  ui_story_5085_50850501_45_dialog_content = "Feast your eyes on this world's one and only Atelier, brought to you by none other than Ryza Stout!",
  ui_story_5085_50850501_46_dialog_content = "And with our work finally complete...",
  ui_story_5085_50850501_47_dialog_content = "It's time to have some real summer fun! Leave the cooking to me; I wanna show everyone how we grill food back in the Rediesel Desert!",
  ui_story_5085_50850501_48_dialog_content = "Okay, I'll go scour the beach for any materials and ingredients for food.",
  ui_story_5085_50850501_49_dialog_content = "And I'll... make some desserts out of everyone's ingredients.",
  ui_story_5085_50850501_50_dialog_content = "I don't feel like going in the water, so I'll just help with preparing the food.",
  ui_story_5085_50850501_51_dialog_content = "Oh come on, Patty! It's no fun unless we all go play on the beach together...",
  ui_story_5085_50850501_52_dialog_content = "Um... Ryza? I think we're forgetting something very important...",
  ui_story_5085_50850501_53_dialog_content = "When we came to this world, we didn't bring any swimsuits.",
  ui_story_5085_50850501_54_dialog_content = "You're right... We could always gather materials for me to make some... But it'll be dark by the time I finish.",
  ui_story_5085_50850501_55_dialog_content = "Oh! Actually... I happen to have an extra swimsuit with me.",
  ui_story_5085_50850501_56_dialog_content = "R-Really?!",
  ui_story_5085_50850501_57_dialog_content = "Uh-huh! I meant to give it to Carleen as a present... She's another close friend of ours.",
  ui_story_5085_50850501_58_dialog_content = "But she's always so busy with work and other official matters. She may not get the chance to wear it before the summer ends.",
  ui_story_5085_50850501_59_dialog_content = "If it's alright with you, you're more than welcome to wear it.",
  ui_story_5085_50850501_60_dialog_content = "<color=#e8d9bb>A while later—</color>",
  ui_story_5085_50850501_61_dialog_content = "Ahh!!",
  ui_story_5085_50850501_62_dialog_content = "What's the matter?!",
  ui_story_5085_50850501_63_dialog_content = "This swimsuit looks amazing! Thank you!",
  ui_story_5085_50850502_1_dialog_content = "Time to play in the water!",
  ui_story_5085_50850502_2_dialog_content = "Wow, that's chilly! Are you sure you don't want to join us, Patty?",
  ui_story_5085_50850502_3_dialog_content = "Positive. Without any extra swimsuits... I refuse to embarrass myself in front of everyone.",
  ui_story_5085_50850502_4_dialog_content = "Really? That's a shame, but oh well! Right this way, everyone; here are the materials we're going to need...",
  ui_story_5085_50850502_5_dialog_content = "<color=#e8d9bb>Splash—</color>",
  ui_story_5085_50850502_6_dialog_content = "Wow! M-Miss Barbara?! What are you...",
  ui_story_5085_50850502_7_dialog_content = "I thought we were playing, weren't we? Better get moving, or I'll really let you have it! Hah!",
  ui_story_5085_50850502_8_dialog_content = "<color=#e8d9bb>Splash—!</color>",
  ui_story_5085_50850502_9_dialog_content = "Heh... In that case, I won't hold back either! Hyaah!",
  ui_story_5085_50850502_10_dialog_content = "Ah! W-Wait a minute, I'm not mentally prepared for this yet...!",
  ui_story_5085_50850502_11_dialog_content = "This is no time for fooling around... Now cover me, PlayerName!",
  ui_story_5085_50850502_12_dialog_content = "<color=#e8d9bb>Splash—!</color>",
  ui_story_5085_50850502_13_dialog_content = "...",
  ui_story_5085_50850502_14_dialog_content = "So that's how it is, huh...",
  ui_story_5085_50850502_15_dialog_content = "Hope you're all ready to lose!!!",
  ui_story_5085_50850502_16_dialog_content = "<color=#e8d9bb>Splash—!</color>",
  ui_story_5085_50850502_17_dialog_content = "<color=#e8d9bb>The sun slowly sets as they play and gather ingredients for a delicious barbecue. By the time their bellies are full, night has already fallen.</color>",
  ui_story_5085_50850502_18_dialog_content = "It's nice to finally relax after such a long and stressful day...",
  ui_story_5085_50850502_19_dialog_content = "I didn't realize my drinks would be so popular, or else I'd have made more! Thankfully, the island offers some truly fresh ingredients.",
  ui_story_5085_50850502_20_dialog_content = "Naturally, we have everyone else to thank for exploring those materials, and Miss Zarya for providing the ice!",
  ui_story_5085_50850502_21_dialog_content = "It was nothing... You're just really talented when it comes to making drinks, Miss Klaudia!",
  ui_story_5085_50850502_22_dialog_content = "Thanks... Even though we...",
  ui_story_5085_50850502_23_dialog_content = "Even though we spent so much time playing that we forgot to gather more materials...",
  ui_story_5085_50850502_24_dialog_content = "I think the fun we had and the memories we made are even more important!",
  ui_story_5085_50850502_25_dialog_content = "Allow me to thank everyone again for sampling my special Rediesel calamari! I put my heart and soul into making it today!",
  ui_story_5085_50850502_26_dialog_content = "Even though there wasn't really enough to go around, and some of the pieces got a little charred...",
  ui_story_5085_50850502_27_dialog_content = "The taste was still out of this world! If only we could use alchemy to restore their outer parts...",
  ui_story_5085_50850502_28_dialog_content = "Speaking of which... can alchemy be used to restore these relic fragments to their original form?",
  ui_story_5085_50850502_29_dialog_content = "Ah, those are the pieces we gathered earlier.",
  ui_story_5085_50850502_30_dialog_content = "I picked up a few myself, but I'm not sure if Ryza can use them or not.",
  ui_story_5085_50850502_31_dialog_content = "You're all such wonderful helpers! Thank you for keeping an eye out for new materials for my alchemy!",
  ui_story_5085_50850502_32_dialog_content = "We won't know unless we try, right? I'll see what I can make out of these pieces tonight!",
  ui_story_5085_50850502_33_dialog_content = "Ever since meeting Ryza, it feels as though I finally have some serious competition when it comes to scavenging!",
  ui_story_5085_50850502_34_dialog_content = "Hahaha, this might just give us more information about the ruins.",
  ui_story_5085_50850502_35_dialog_content = "I can't sense anything from these individual fragments.",
  ui_story_5085_50850502_36_dialog_content = "But once they've been restored... It might be a completely different story!",
  ui_story_5085_50850502_37_dialog_content = "I'll go tidy up the atelier so that everyone can get a good night's rest.",
  ui_story_5085_50850601_1_dialog_content = "<color=#e8d9bb>Squawk—Squawk—</color>",
  ui_story_5085_50850601_2_dialog_content = "... Huh?! Oh... I guess they have nocturnal sea birds in this world too...",
  ui_story_5085_50850601_3_dialog_content = "It's okay, they shouldn't wake anyone up.",
  ui_story_5085_50850601_4_dialog_content = "Everyone's exhausted after today... They're all fast asleep.",
  ui_story_5085_50850601_5_dialog_content = "Are you still watching over the cauldron, Ryza?",
  ui_story_5085_50850601_6_dialog_content = "That's right! I have to keep a close eye on the contents to make sure nothing goes wrong.",
  ui_story_5085_50850601_7_dialog_content = "Hmm, not bad at all... A little longer and the fragments should be back in their original shape!",
  ui_story_5085_50850601_8_dialog_content = "It sounds like you're no stranger to stirring a cauldron all night long. Being an alchemist must be really tough...",
  ui_story_5085_50850601_9_dialog_content = "Alchemy is the art of creating something out of nothing. Over the ages, alchemists have experimented with countless ideas and methods to give us the knowledge that we have today.",
  ui_story_5085_50850601_10_dialog_content = "Ahhh, but I still can't help but worry. What'll we do if something does go wrong...?",
  ui_story_5085_50850601_11_dialog_content = "Haha, then I'll stay up with you until it's done. I'm sure everything will be alright!",
  ui_story_5085_50850601_12_dialog_content = "Actually, when I used my powers to sense this cauldron... I heard a strange voice.",
  ui_story_5085_50850601_13_dialog_content = "It told me to come back.",
  ui_story_5085_50850601_14_dialog_content = "Eh?!",
  ui_story_5085_50850601_15_dialog_content = "Is that so? Do you think it was the cauldron talking to you?",
  ui_story_5085_50850601_16_dialog_content = "Maybe. My psychic powers tell me that this voice is somehow connected to the ruins.",
  ui_story_5085_50850601_17_dialog_content = "It sounded like an ancient spirit... And it tried to communicate with me by speaking as though it knew me.",
  ui_story_5085_50850601_18_dialog_content = "I'm not sure whether or not to follow this clue. I don't even know where I could start...",
  ui_story_5085_50850601_19_dialog_content = "I have a question!",
  ui_story_5085_50850601_20_dialog_content = "It's about your powers. If you can't sense any Eclipsites around, then that means we won't run into any, right?",
  ui_story_5085_50850601_21_dialog_content = "Yeah, that's usually the case...",
  ui_story_5085_50850601_22_dialog_content = "I see. What an interesting power... Hah!",
  ui_story_5085_50850601_23_dialog_content = "<color=#e8d9bb>Squish!</color>",
  ui_story_5085_50850601_24_dialog_content = "W-What was that about...?!",
  ui_story_5085_50850601_25_dialog_content = "Don't worry, it was just a bug. It looks like there are some things that even your powers can't detect, huh?",
  ui_story_5085_50850601_26_dialog_content = "It looks like a mosquito, but take a closer look! Its eyes are completely red, and it's disappearing shortly after I killed it... There's a good chance it's some kind of Eclipsite mosquito.",
  ui_story_5085_50850601_27_dialog_content = "And yet you didn't even notice it! Could this mean the island possesses other unique properties?",
  ui_story_5085_50850601_28_dialog_content = "It sure looks that way...",
  ui_story_5085_50850601_29_dialog_content = "This island really is full of mysteries.",
  ui_story_5085_50850601_30_dialog_content = "I agree, and something tells me the island and its ruins want us to uncover their secrets as well.",
  ui_story_5085_50850601_32_dialog_content = "It's funny, you were telling me your story before that bird interrupted...",
  ui_story_5085_50850601_33_dialog_content = "But now, you're listening to me talk about my worries...",
  ui_story_5085_50850601_35_dialog_content = "If we ever find the time, I still want to hear more about your adventures!",
  ui_story_5085_50850601_37_dialog_content = "It sounds like you really love adventures, Ryza.",
  ui_story_5085_50850601_38_dialog_content = "But I can totally relate, because I do too!",
  ui_story_5085_50850601_39_dialog_content = "Whether it's seeing strange new things or traveling with my friends... I always cherish every moment of every adventure!",
  ui_story_5085_50850601_40_dialog_content = "<color=#e8d9bb>Between the two kindred spirits, the alchemy cauldron seems to resonate with their passion for adventure and makes a promising sound.</color>",
  ui_story_5085_50850601_41_dialog_content = "We did it!",
  ui_story_5085_50850601_42_dialog_content = "The fragments have been restored to their original form... Wait, there's three of them now! Any idea what this is?",
  ui_story_5085_50850601_43_dialog_content = "It's...",
  ui_story_5085_50850601_44_dialog_content = "... Some kind of <color=#FFB400>emblem</color>?",
  ui_story_5085_50850601_45_dialog_content = "It is, and there are three different kinds of them! They're all so pretty!",
  ui_story_5085_50850601_46_dialog_content = "Check out this one! It looks like something's engraved on it... A shield, maybe? I wonder what it could mean?",
  ui_story_5085_50850601_47_dialog_content = "Let me try sensing it.",
  ui_story_5085_50850601_48_option_content = "Force Boost",
  ui_story_5085_50850601_49_dialog_content = "My prince, there isn't much time left. We must make a decision before it's too late.",
  ui_story_5085_50850601_50_dialog_content = "The ancient relic you've introduced to us works quite well, but we have yet to master its controls.",
  ui_story_5085_50850601_51_dialog_content = "The ranks of the Eclipsites swell with each passing day, and we're heartbroken to see you in such a haggard and anxious state...",
  ui_story_5085_50850601_52_dialog_content = "The Musician tells us that you plan to leave the kingdom and travel to a distant land.",
  ui_story_5085_50850601_53_dialog_content = "But no matter what happens, your highness... We'll always honor your decision...",
  ui_story_5085_50850601_54_dialog_content = "Are these the memories of the knight on that emblem? It sounds like he's talking about the island's ruins... This might even tell us more about the teleportation!",
  ui_story_5085_50850601_55_dialog_content = "Please, can you show me how to use the power of the ruins?",
  ui_story_5085_50850601_56_dialog_content = "Come back.",
  ui_story_5085_50850601_57_dialog_content = "... That voice again! Who are you?! Could it be that you're...",
  ui_story_5085_50850601_58_dialog_content = "Come back! Your glory awaits...!",
  ui_story_5085_50850601_59_dialog_content = "<size=50>\"For when the wandering prince returns, so too shall the glory of our kingdom!\"</size>",
  ui_story_5085_50850601_60_dialog_content = "... Huh?!?",
  ui_story_5085_50850601_61_option_content = "Mind... Mindlink!",
  ui_story_5085_50850601_62_dialog_content = "Urgh...",
  ui_story_5085_50850601_63_dialog_content = ".. PlayerName! What's the matter?!",
  ui_story_5085_50850601_64_dialog_content = "Don't try to do it all by yourself! You still have me, as well as the rest of our friends!",
  ui_story_5085_50850601_65_dialog_content = "... Friends...",
  ui_story_5085_50850601_66_dialog_content = "There are rumors of ancient mechs in the ruins. My curiosity was getting the better of me. I had to see for myself.",
  ui_story_5085_50850601_67_dialog_content = "Or some legendary ancient mechas!",
  ui_story_5085_50850601_68_dialog_content = "... It's Fleur! This is Fleur's voice! What have you done to him?!",
  ui_story_5085_50850601_69_dialog_content = "Come back... Return... to the ruins...",
  ui_story_5085_50850601_70_dialog_content = "No, stay away! The ruins are dangerous! The consciousness housed within them has altered my memories and taken over my body!",
  ui_story_5085_50850601_71_dialog_content = "Whatever you do... Don't come near the ruins!!!",
  ui_story_5085_50850601_72_dialog_content = "!!!",
  ui_story_5085_50850601_73_dialog_content = "PlayerName! Snap out of it!",
  ui_story_5085_50850601_74_dialog_content = "Eclipsites showed up while you were using your powers! We have to fight!",
  ui_story_5085_50850602_1_dialog_content = "Hah! There's no escape!",
  ui_story_5085_50850602_2_dialog_content = "Ryza! Navigator!",
  ui_story_5085_50850602_3_dialog_content = "We heard a disturbance over here! Are either of you hurt?",
  ui_story_5085_50850602_4_dialog_content = "No, we're fine...",
  ui_story_5085_50850602_5_dialog_content = "A huge noise just roared across the entire island, as though the whole thing started to move or something.",
  ui_story_5085_50850602_6_dialog_content = "The Eclipsites seem a lot more agitated too.",
  ui_story_5085_50850602_7_dialog_content = "Wow, I wonder if we stumbled across yet another secret?",
  ui_story_5085_50850602_8_dialog_content = "Wh-What kind of secret are you talking about?!",
  ui_story_5085_50850602_9_dialog_content = "It has to do with the emblems we restored and the kingdom that used to exist here... And also what this island has done to us!",
  ui_story_5085_50850602_10_dialog_content = "<color=#e8d9bb>Under the gloomy moonlight, the history of the ancient kingdom is slowly revealed to all...</color>",
  ui_story_5085_50850602_11_dialog_content = "... And that's more or less what happened. We have to rescue Fleur and get rid of the malevolent presence controlling his body!",
  ui_story_5085_50850602_12_dialog_content = "A magic that can erase the memories of one's friends... How despicable.",
  ui_story_5085_50850602_13_dialog_content = "Even though I remember him now, I still feel awful about forgetting...",
  ui_story_5085_50850602_14_dialog_content = "How dare those stinking ruins cast a spell on me! Mark my words, I'll turn them into an even bigger pile of rubble before we're done here!",
  ui_story_5085_50850602_15_dialog_content = "So it seems... The power of these ruins is what brought us here from our own world...",
  ui_story_5085_50850602_17_dialog_content = "Based on what Ryza and the Navigator, these three emblems might hold the key to defeating the ruins.",
  ui_story_5085_50850602_18_dialog_content = "No matter what this thing might be, we won't get anywhere unless we investigate it ourselves!",
  ui_story_5085_50850602_20_dialog_content = "I agree. Whether it's someone's lingering resentment or technology from the past, there's always a solution. Now let's get ready to go!",
  ui_story_5085_50850602_21_dialog_content = "While everyone is making their preparations, I'll sense the other two emblems and see what else I can find.",
  ui_story_5085_50850701_1_dialog_content = "Force Boost",
  ui_story_5085_50850701_2_dialog_content = "Three emblems... correspond to the prince's three closest companions.",
  ui_story_5085_50850701_3_dialog_content = "A valiant knight who fights off enemies with his sword...",
  ui_story_5085_50850701_4_dialog_content = "A mage who studies ancient history in search of arcane wisdom...",
  ui_story_5085_50850701_5_dialog_content = "And a court musician, whose melodies can embolden even the most wavering hearts...",
  ui_story_5085_50850701_6_dialog_content = "They were the prince's most loyal subjects, and they fought at his side through thick and thin.",
  ui_story_5085_50850701_7_dialog_content = "But when he left, the three of them stayed behind to herald his return...",
  ui_story_5085_50850701_8_dialog_content = "\"For when the wandering prince returns, so too shall the glory of our kingdom!\"",
  ui_story_5085_50850701_9_dialog_content = "I see. So that's what it means.",
  ui_story_5085_50850701_10_dialog_content = "But the kingdom is nothing but ruins now... And on top of that, the ruins have completely lost control.",
  ui_story_5085_50850701_11_dialog_content = "Does this mean that the prince never returned, even though his kingdom was under attack by the Eclipsites?",
  ui_story_5085_50850701_12_dialog_content = "Meanwhile, his three closest friends stayed on the island to wait for him...",
  ui_story_5085_50850701_13_dialog_content = "But now that none of them are here, the consciousness within the ruins has slowly started losing control...",
  ui_story_5085_50850701_14_dialog_content = "Randomly choosing to seize people in the name of the prince?",
  ui_story_5085_50850701_16_dialog_content = "Why would he abandon the island when he had the protection of both the ancient ruins and his closest friends?",
  ui_story_5085_50850701_18_dialog_content = "He may sound like a coward... But perhaps he had a reason for not returning?",
  ui_story_5085_50850701_19_dialog_content = "Well, we're not gonna get any closer to the truth if we just keep sitting around and guessing like this.",
  ui_story_5085_50850701_20_dialog_content = "The answers are most likely waiting for us at the end of our adventure.",
  ui_story_5085_50850701_21_dialog_content = "That's right! Our mission is to uncover the secrets of those ruins and rescue Navigator's friend!",
  ui_story_5085_50850701_22_dialog_content = "Agreed. The road ahead won't be an easy one, but we can't afford to back down.",
  ui_story_5085_50850702_1_dialog_content = "<color=#e8d9bb>As we made our way through the forest, I kept my mind alert for any sign of our objective.</color>",
  ui_story_5085_50850702_2_dialog_content = "<color=#e8d9bb>But when we crested the top of a mountain, the ruins finally came into view.</color>",
  ui_story_5085_50850702_3_dialog_content = "We... We finally... made it to this point!",
  ui_story_5085_50850702_4_dialog_content = "Is this ancient stone gate the entrance to the ruins? If so... How are we supposed to get in...?",
  ui_story_5085_50850702_5_dialog_content = "Hey! Look at these slots in the gate, everyone!",
  ui_story_5085_50850702_6_dialog_content = "They seem to match the shape of those three emblems perfectly! Maybe they really are the keys!",
  ui_story_5085_50850702_7_dialog_content = "PlayerName, can you sense if there are any Eclipsites nearby?",
  ui_story_5085_50850702_8_option_content = "Mindlink!",
  ui_story_5085_50850702_9_dialog_content = "There aren't any Eclipsites on the other side of the gate, but...",
  ui_story_5085_50850702_10_dialog_content = "There's definitely something over there...",
  ui_story_5085_50850702_11_dialog_content = "You can feel it too, Ryza?",
  ui_story_5085_50850702_12_dialog_content = "Maybe it's because I'm holding this emblem, but feel a powerful sense of yearning coming from the other side. It's so sad... And yet oddly comforting.",
  ui_story_5085_50850702_13_dialog_content = "Let's just put the emblems in place first.",
  ui_story_5085_50850702_14_dialog_content = "<color=#e8d9bb>Click, click, click—</color>",
  ui_story_5085_50850702_15_dialog_content = "<color=#e8d9bb>Rumble—</color>",
  ui_story_5085_50850702_16_dialog_content = "Wh-What's happening?!",
  ui_story_5085_50850702_17_dialog_content = "Wait... Someone's coming!",
  ui_story_5085_50850702_18_dialog_content = "Up there!!",
  ui_story_5085_50850702_19_dialog_content = "You're right... But when did they appear?!",
  ui_story_5085_50850702_20_dialog_content = "Welcome to my kingdom—",
  ui_story_5085_50850702_21_dialog_content = "F-Fleur?!",
  ui_story_5085_50850702_22_dialog_content = "No, it's the consciousness within the ruins! It's controlling Fleur's body...",
  ui_story_5085_50850702_23_dialog_content = "And forcing him to act as the \"wandering prince\"!",
  ui_story_5085_50850702_24_dialog_content = "I bid you good morning, my wandering Caelestite friend.",
  ui_story_5085_50850702_25_dialog_content = "The actors in this play matter little. In his search for you, he stumbled upon this place...",
  ui_story_5085_50850702_26_dialog_content = "And so the ruins cast him as the prince.",
  ui_story_5085_50850702_27_dialog_content = "Ah—How I've lamented the loss of my kingdom, and how nary a soul came to its defense! But now, the time has come to summon my most loyal subjects.",
  ui_story_5085_50850702_28_option_content = "Force Boost!",
  ui_story_5085_50850702_29_dialog_content = "Fleur! Snap out of it!",
  ui_story_5085_50850702_30_dialog_content = "Whoa—",
  ui_story_5085_50850702_31_dialog_content = "My head... It's throbbing all of a sudden...",
  ui_story_5085_50850702_32_dialog_content = "Y-Your power is not working, ! Using them will only make the \"prince\" exert psychic pressure on all of us...",
  ui_story_5085_50850702_33_dialog_content = "Your desperate cries are music to my ears. Through your own recklessness actions, you have brought pain and suffering unto your subjects—",
  ui_story_5085_50850702_34_dialog_content = "They aren't my subjects! They're my friends! And—",
  ui_story_5085_50850702_35_dialog_content = "You're one of us too!!!",
  ui_story_5085_50850702_36_dialog_content = "...",
  ui_story_5085_50850702_37_dialog_content = "I... am an actor... Blessed with the memories of the prince...",
  ui_story_5085_50850702_38_dialog_content = "Ahem... Now, let us continue our glorious performance...",
  ui_story_5085_50850702_39_dialog_content = "Travelers from afar! What proof have you of identifying yourselves as my most loyal subjects?",
  ui_story_5085_50850702_40_dialog_content = "There is but one way forward: complete my quests, and awaken the memories within these emblems!",
  ui_story_5085_50850702_41_dialog_content = "Only then shall I grant you passage.",
  ui_story_5085_50850702_42_dialog_content = "Huh?? Does that mean you'll let us into the ruins?",
  ui_story_5085_50850702_43_dialog_content = "We just need to complete these \"quests,\" right?",
  ui_story_5085_50850702_44_dialog_content = "Then there's still hope! As long as we manage to get into the ruins, we have a chance to save Fleur!",
  ui_story_5085_50850702_45_dialog_content = "Heed my words, travelers! The quests of the Knight's Emblems—",
  ui_story_5085_50850702_46_dialog_content = "\"Slay one hundred blood-sucking monsters, so that our kingdom may finally sleep in peace and comfort.\"",
  ui_story_5085_50850702_47_dialog_content = "\"Blood-sucking monsters\"...? A-Are there truly such scary creatures on this island?",
  ui_story_5085_50850702_48_dialog_content = "A blood-sucking monster... Could it be that thing I saw with PlayerName before?",
  ui_story_5085_50850702_49_dialog_content = "Next is the quest of the Musician's Emblem—",
  ui_story_5085_50850702_50_dialog_content = "\"Offer our kingdom's soldiers a restful night of sleep with the most soothing lullaby in the world.\"",
  ui_story_5085_50850702_51_dialog_content = "... A lullaby?!",
  ui_story_5085_50850702_52_dialog_content = "That's the worst-case scenario for a hard-rocking idol like me!!",
  ui_story_5085_50850702_53_dialog_content = "And finally, the quest of the Mage's Emblem—",
  ui_story_5085_50850702_54_dialog_content = "\"Summon a miraculous wind to cradle the palace in a soft, pleasant breeze forevermore.\"",
  ui_story_5085_50850702_55_dialog_content = "...",
  ui_story_5085_50850702_56_dialog_content = "...",
  ui_story_5085_50850702_57_dialog_content = "Why do all of these quests have something to do with sleeping?!?",
  ui_story_5085_50850702_58_dialog_content = "Heheheh... Looks like the prince has some serious insomnia...",
  ui_story_5085_50850702_59_dialog_content = "Is this why the prince left his kingdom in the first place? Ridiculous—",
  ui_story_5085_50850702_60_dialog_content = "I wonder... How are we supposed to create a perpetual breeze to \"cradle the palace\"?",
  ui_story_5085_50850702_62_dialog_content = "When the three emblems awaken, our kingdom shall be born anew.",
  ui_story_5085_50850702_63_dialog_content = "I'm confident that... You will find the answers.",
  ui_story_5085_50850702_64_dialog_content = "What a troublesome set of quests.",
  ui_story_5085_50850702_65_dialog_content = "I'm just grateful we've been given a way forward. At least we know what we need to do now.",
  ui_story_5085_50850702_66_dialog_content = "What do you think, Ryza?",
  ui_story_5085_50850702_67_dialog_content = "Let's just keep moving. I'm sure the answer will reveal itself soon enough.",
  ui_story_5085_50850702_68_dialog_content = "In fact... I already have a few ideas for completing these quests!",
  ui_story_5085_50850800_1_dialog_content = "Uh-oh, we have more Eclipsites!",
  ui_story_5085_50850800_2_dialog_content = "Where are we supposed to find these \"blood-sucking monsters\" for the Knight's quest?",
  ui_story_5085_50850800_3_dialog_content = "Actually, the Navigator and I have already had a plan for that!",
  ui_story_5085_50850800_4_dialog_content = "That's why I think the Knight's Emblem quest shouldn't be a problem for us!",
  ui_story_5085_50850800_5_dialog_content = "The Mage's quest will probably be the most troublesome... How are we supposed to create something that can summon a perpetual breeze?",
  ui_story_5085_50850800_6_dialog_content = "Actually, I have a few ideas that might be of use to you, Ryza!",
  ui_story_5085_50850900_1_dialog_content = "Excellent... Thanks to Miss Vice's help, it looks like Ryza has discovered a new direction to explore with her alchemy.",
  ui_story_5085_50850900_2_dialog_content = "Really? That's great! I've been making progress on my side as well.",
  ui_story_5085_50850900_3_dialog_content = "Soon, we'll have two awakened emblems in our possession!",
  ui_story_5085_50850900_4_dialog_content = "What about you, Klaudia? You and Barbara seem to be working quite well together.",
  ui_story_5085_50850900_5_dialog_content = "We've made plenty of progress too, but I'm still a bit nervous...",
  ui_story_5085_50850902_1_dialog_content = "Sorry for the wait—",
  ui_story_5085_50850902_2_dialog_content = "I think... I think we've done it!",
  ui_story_5085_50850902_3_dialog_content = "I bet the prince wasn't expecting us to complete his quests so quickly!",
  ui_story_5085_50850902_4_dialog_content = "Hey—consciousness of the ruins, or whoever you are—",
  ui_story_5085_50850902_5_dialog_content = "We're finished with all three of your quests!",
  ui_story_5085_50850902_6_dialog_content = "... You must first tell me how you accomplished your goals.",
  ui_story_5085_50850902_7_dialog_content = "Let's get started.",
  ui_story_5085_50850902_8_dialog_content = "Right!",
  ui_story_5085_50850902_9_dialog_content = "First, the Knight's Emblem!",
  ui_story_5085_50850902_10_dialog_content = "... Zarya and I completed that one together!",
  ui_story_5085_50850902_11_dialog_content = "A-As a royal guardian of Queen Bethlehem... I'm more than willing to undertake a knight's quest!",
  ui_story_5085_50850902_12_dialog_content = "With our combined strength, we eliminated one hundred Eclipsite mosquitos from the island!",
  ui_story_5085_50850902_13_dialog_content = "That should satisfy the quest's requirement of slaying \"one hundred blood-sucking monsters,\" yes?",
  ui_story_5085_50850902_14_dialog_content = "I just wish we could've included the one Ryza and I swatted the night before...",
  ui_story_5085_50850902_15_dialog_content = "Next, the Musician's Emblem!",
  ui_story_5085_50850902_16_dialog_content = "Yeah, yeah, yeah! When it comes to music, no challenge is too great for the number-one idol, Barbara!",
  ui_story_5085_50850902_17_dialog_content = "And with Miss Klaudia's incredible support...",
  ui_story_5085_50850902_18_dialog_content = "Our already-wonderful music became an unstoppable force of sonic superiority!",
  ui_story_5085_50850902_19_dialog_content = "Heheh, I simply provided instrumental accompaniment for Miss Barbara's beautiful voice.",
  ui_story_5085_50850902_20_dialog_content = "Her singing is truly spectacular!",
  ui_story_5085_50850902_21_dialog_content = "All we did was change the mode of expression; the love in my heart still burns as hot as ever!",
  ui_story_5085_50850902_22_dialog_content = "And with that, we gave the kingdom's soldiers the sweetest lullaby they've ever heard!",
  ui_story_5085_50850902_23_dialog_content = "And finally, the Mage's Emblem!",
  ui_story_5085_50850902_24_dialog_content = "Behold! This is the power—",
  ui_story_5085_50850902_25_dialog_content = "Of my alchemy! With everyone's help, we created the ultimate wind-generator!",
  ui_story_5085_50850902_26_dialog_content = "I provided the design, Zarya provided the ice cubes, and Ryza provided the parts. After that, we all worked together to assemble it.",
  ui_story_5085_50850902_27_dialog_content = "Though back in Illumina, we would refer to it as an \"air conditioner\" or something along those lines...",
  ui_story_5085_50850902_28_dialog_content = "But the name's not important!",
  ui_story_5085_50850902_29_dialog_content = "With this machine, we were able to summon a miraculous wind to \"cradle the palace in a soft, pleasant breeze\"!",
  ui_story_5085_50850902_30_dialog_content = "For the ancient Aurorians who once lived here, such an advanced and convenient device would have been even more impressive than magic!",
  ui_story_5085_50850902_31_dialog_content = "I see... So these are the answers you have brought to me.",
  ui_story_5085_50850902_32_dialog_content = "Even so...",
  ui_story_5085_50850902_33_dialog_content = "Before granting you entry, I must be certain of your loyalty.",
  ui_story_5085_50850902_34_dialog_content = "Now you must prove to me that friendship is worth more than gold!",
  ui_story_5085_50850902_35_dialog_content = "After all of that running around, now you want us to prove our friendship?!",
  ui_story_5085_50850902_36_dialog_content = "Maybe he just wants us to prove the friendship between the prince and the owners of these emblems?",
  ui_story_5085_50850902_37_dialog_content = "But that's completely redundant!",
  ui_story_5085_50850902_38_dialog_content = "That's fine, I'd be happy to prove it to you!",
  ui_story_5085_50850902_39_dialog_content = "Huh?",
  ui_story_5085_50850902_40_dialog_content = "And that's because—We are the prince's closest friends!",
  ui_story_5085_50850902_41_dialog_content = "Everything we've done so far is in service of the \"current\" prince. That much is entirely true.",
  ui_story_5085_50850902_42_dialog_content = "And if you don't believe me, I'll use the warmth in my hands to prove it to you!",
  ui_story_5085_50850902_43_dialog_content = "...",
  ui_story_5085_50850902_44_dialog_content = "Come on, everyone! Help the Navigator push open the gate!",
  ui_story_5085_50850902_45_dialog_content = "Ryza... PlayerName...",
  ui_story_5085_50850902_46_dialog_content = "We can't afford to be stopped in a place like this! Let's go!",
  ui_story_5085_50850902_47_dialog_content = "I'll help PlayerName too!",
  ui_story_5085_50850902_48_dialog_content = "One of the Rediesel Wrench's own is in there! I have a duty to bring him home!",
  ui_story_5085_50850902_49_dialog_content = "I-I swore to myself... That I would never lose to anyone ever again!",
  ui_story_5085_50850902_50_dialog_content = "\"Place your hands on the gate and open it with your hearts.\"",
  ui_story_5085_50850902_51_dialog_content = "This warmth... This passion...",
  ui_story_5085_50850902_52_dialog_content = "The glory of our past has finally resurfaced.",
  ui_story_5085_50850902_53_dialog_content = "The doors to my kingdom are open to you!",
  ui_story_5085_50850902_54_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5085_50850902_55_dialog_content = "We did it!",
  ui_story_5085_50851001_1_dialog_content = "We finally made it into the ruins!",
  ui_story_5085_50851001_2_dialog_content = "Wow, it's just as incredible from the inside! I bet this place looked really impressive back in the day!",
  ui_story_5085_50851001_3_dialog_content = "We should still be cautious. Time has eaten away at much of the interior...",
  ui_story_5085_50851001_4_dialog_content = "We can't forget about the consciousness either. There's no telling what he's plotting right now.",
  ui_story_5085_50851001_5_dialog_content = "Ugh! We finally got the gate open, but Fleur is nowhere to be found again!",
  ui_story_5085_50851001_6_dialog_content = "Look over there—Is that the throne?",
  ui_story_5085_50851001_7_dialog_content = "There's someone sitting on it! Maybe it's Fleur...",
  ui_story_5085_50851001_8_dialog_content = "Hey, it really is him!",
  ui_story_5085_50851001_9_dialog_content = "Fleur—!",
  ui_story_5085_50851001_10_dialog_content = "...",
  ui_story_5085_50851001_11_option_content = "Mindlink—",
  ui_story_5085_50851001_12_dialog_content = "<color=#e8d9bb>Crackle—</color>",
  ui_story_5085_50851001_13_dialog_content = "I don't recall when it started, but the Eclipsites began attacking us every single night.",
  ui_story_5085_50851001_14_dialog_content = "To this day, I still don't know when or why they appeared, but they have brought my people untold pain and suffering.",
  ui_story_5085_50851001_15_dialog_content = "Night after sleepless night, I watched as my friends and loved ones were taken from me one by one.",
  ui_story_5085_50851001_16_dialog_content = "And so I've decided to leave the kingdom and seek aid from the mainland. The king should not be forced to face this crisis alone.",
  ui_story_5085_50851001_17_dialog_content = "O wise and ancient spirit of the ruins... Please remember my intentions.",
  ui_story_5085_50851001_18_dialog_content = "If I should return victorious, promise me that you will sing my praises. But should I never return, please do not mourn me...",
  ui_story_5085_50851001_19_dialog_content = "These <color=#FFB400>three emblems</color> symbolize three people of the highest moral character.",
  ui_story_5085_50851001_20_dialog_content = "In the hands of the worthy, these emblems will bring new life to our kingdom someday...",
  ui_story_5085_50851001_21_dialog_content = "Prince...",
  ui_story_5085_50851001_22_dialog_content = "Well?",
  ui_story_5085_50851001_23_dialog_content = "... Fleur still hasn't regained consciousness, but I think I know why you and your friends were summoned to this world, Ryza...",
  ui_story_5085_50851001_24_dialog_content = "Huh?!",
  ui_story_5085_50851001_25_dialog_content = "The prince left the island to ask for help from the mainland, and he entrusted the ruins with his final message.",
  ui_story_5085_50851001_26_dialog_content = "If he failed to return, the kingdom was to be left in the hands of the three people bearing these emblems...",
  ui_story_5085_50851001_27_dialog_content = "The Knight, the Mage, and the Musician...?",
  ui_story_5085_50851001_28_dialog_content = "Then that must mean... The prince never made it back...",
  ui_story_5085_50851001_29_dialog_content = "That's right, and in the countless years following the fall of his kingdom...",
  ui_story_5085_50851001_30_dialog_content = "The ruins have been waiting for the prince's return, and searching endlessly for three worthy people to take these emblems and restore the kingdom.",
  ui_story_5085_50851001_31_dialog_content = "And since you were all worthy of the emblems, the ruins summoned you here from another world by mistake. If I had to guess, that's probably around the time Fleur was mistaken for the prince and trapped here.",
  ui_story_5085_50851001_32_dialog_content = "So that's how it happened! Then the real prince...",
  ui_story_5085_50851001_33_dialog_content = "Whether it was to seek help on the mainland, or to return home safely, both are but an unattainable dream for him now.",
  ui_story_5085_50851001_34_dialog_content = "What a terrible way for things to end...",
  ui_story_5085_50851001_35_dialog_content = "Look out! Above us!!",
  ui_story_5085_50851001_36_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5085_50851001_37_dialog_content = "The ruins are starting to shake!",
  ui_story_5085_50851001_38_dialog_content = "Ah... Ahhhhhhh—",
  ui_story_5085_50851001_39_dialog_content = "Fleur?! Wh-Wh-What's the matter with you?!",
  ui_story_5085_50851001_40_dialog_content = "Ah!",
  ui_story_5085_50851001_41_dialog_content = "We have to get out of here! If the ruins are losing control, then Fleur is—",
  ui_story_5085_50851001_42_dialog_content = "Fleur... He's becoming one with the stone and machinery of the ruins!",
  ui_story_5085_50851001_43_dialog_content = "Is he turning himself into a mecha?!",
  ui_story_5085_50851001_44_dialog_content = "Huh?",
  ui_story_5085_50851001_45_dialog_content = "So are the ruins doing this? Or could it be that Fleur is finally resisting their control?",
  ui_story_5085_50851001_46_dialog_content = "I don't think that's our biggest concern right now!",
  ui_story_5085_50851001_47_dialog_content = "He's going to level this entire place if we don't stop him soon!!!",
  ui_story_5085_50851001_48_dialog_content = "The kingdom must be reborn... I must realize our dream!",
  ui_story_5085_50851001_49_dialog_content = "Hraaaaaah—!",
  ui_story_5085_50851002_1_dialog_content = "He's starting to fall apart! Now, Navigator!",
  ui_story_5085_50851002_2_dialog_content = "Got it!",
  ui_story_5085_50851002_3_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5085_50851002_4_dialog_content = "Fleur! Are you alright?!",
  ui_story_5085_50851002_5_dialog_content = "My mecha... My kingdom...",
  ui_story_5085_50851002_6_dialog_content = "He still hasn't snapped out of it... I'll just carry him out of here... Hmm?",
  ui_story_5085_50851002_7_dialog_content = "?!?",
  ui_story_5085_50851002_8_dialog_content = "You three are suddenly glowing...",
  ui_story_5085_50851002_9_dialog_content = "... Just like the three emblems!",
  ui_story_5085_50851002_10_dialog_content = "I see... The prince wanted us to gather here all along.",
  ui_story_5085_50851002_11_dialog_content = "And now that his consciousness is gone... It's time for the chosen saviors of his kingdom to return as well.",
  ui_story_5085_50851002_12_dialog_content = "But...",
  ui_story_5085_50851002_13_dialog_content = "The ruins... And this entire mountain! They're all about to collapse!",
  ui_story_5085_50851002_14_dialog_content = "It's not just the mountain... The whole island is trembling! What should we do...?",
  ui_story_5085_50851002_15_dialog_content = "Head for the beach. Your friend is waiting for you there.",
  ui_story_5085_50851002_16_dialog_content = "Fleur? No wait... You're the prince, aren't you? What do you mean by \"our friend\"?",
  ui_story_5085_50851002_17_dialog_content = "He's right, you know! At least we'll be safe from falling debris at the beach, so let's hurry!",
  ui_story_5085_50851002_18_dialog_content = "Then it looks like our final quest...",
  ui_story_5085_50851002_19_dialog_content = "Is to escort everyone safely to the beach before we return to our own world! There's still time!",
  ui_story_5085_50851002_20_dialog_content = "Right! Let's hurry!",
  ui_story_5085_50851002_21_dialog_content = "You guys...",
  ui_story_5085_50851002_22_dialog_content = "I just hope we'll have a chance to say our goodbyes once we get there!",
  ui_story_5085_50851100_1_dialog_content = "Hey—over here—",
  ui_story_5085_50851100_2_dialog_content = "Mr. Corax—!",
  ui_story_5085_50851100_3_dialog_content = "(So the friend he mentioned was Corax, huh.)",
  ui_story_5085_50851100_4_dialog_content = "Is everyone safe? The rescue ship will make landfall soon, so please hold on just a bit longer.",
  ui_story_5085_50851100_5_dialog_content = "Phew... We finally made it to the boat. We're not forgetting anyone this time, are we?",
  ui_story_5085_50851100_6_dialog_content = "I don't see Ryza anywhere... Ryza! Where are you?!",
  ui_story_5085_50851100_7_dialog_content = "I'm... I'm here!",
  ui_story_5085_50851100_8_dialog_content = "Sorry if I made anyone worry.",
  ui_story_5085_50851100_9_dialog_content = "If everyone's here now, I'll go let Mr. Corax know we're ready to set sail.",
  ui_story_5085_50851100_10_dialog_content = "The island... In the end, it sank into the sea...",
  ui_story_5085_50851100_11_dialog_content = "Yeah, and without a trace of its existence left behind.",
  ui_story_5085_50851100_12_dialog_content = "There goes my money for maintaining the Colossus...",
  ui_story_5085_50851100_13_dialog_content = "Heheh, I wouldn't be so sure! Take a look at this, everyone—",
  ui_story_5085_50851100_14_dialog_content = "Are these... The fragments of the king's throne? Is this why you took so long to come back, Ryza?!",
  ui_story_5085_50851100_15_dialog_content = "Yep! Even though it was dangerous, you kept using your powers to search for the truth... So naturally I had to help in my own way, too!",
  ui_story_5085_50851100_17_dialog_content = "Ryza...",
  ui_story_5085_50851100_18_dialog_content = "She really outdid herself this time...",
  ui_story_5085_50851100_19_dialog_content = "Let's see what the last remaining fragments of those ruins can tell us—",
  ui_story_5085_50851100_20_dialog_content = "To His Royal Highness Prince,",
  ui_story_5085_50851100_21_dialog_content = "The Eclipsites have grown even more savage, and the power of the ruins has started to wane. I fear that our island kingdom will not stand for much longer.",
  ui_story_5085_50851100_22_dialog_content = "And so, we have decided to follow in your noble footsteps, and lead our people to the mainland in search of a new home.",
  ui_story_5085_50851100_23_dialog_content = "We may not be able to sing your praises upon your triumphant return...",
  ui_story_5085_50851100_24_dialog_content = "But rest assured that your people have not been vanquished. They have simply chosen to start anew in a foreign land.",
  ui_story_5085_50851100_25_dialog_content = "May we cross paths and reunite with one another on the bright and prosperous mainland.",
  ui_story_5085_50851100_26_dialog_content = "So the kingdom was never wiped out in the first place!",
  ui_story_5085_50851100_27_dialog_content = "They traveled to Astra's mainland and found new lives there!",
  ui_story_5085_50851100_28_dialog_content = "Even though the prince never returned from his adventure, his actions paved the way for his people's survival...",
  ui_story_5085_50851100_29_dialog_content = "Not only does that make him a worthy prince, but a brave adventurer as well!",
  ui_story_5085_50851100_30_dialog_content = "If their descendants knew all of this... Would they try to reunite with one another on the mainland?",
  ui_story_5085_50851100_32_dialog_content = "No matter how much time passes, their hearts will always be united. In fact, I'm sure they already reunited with each other somewhere.",
  ui_story_5085_50851100_33_dialog_content = "I think so too! I can feel the burning-hot love that binds their hearts together!",
  ui_story_5085_50851100_34_dialog_content = "It may not be the perfect ending to their story...",
  ui_story_5085_50851100_35_dialog_content = "But it's still a good one... And that should be more than enough.",
  ui_story_5085_50851100_36_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5085_50851100_37_dialog_content = "...",
  ui_story_5085_50851100_38_dialog_content = "Oh... It looks like it's time for us to say goodbyes now.",
  ui_story_5085_50851100_39_dialog_content = "If we ever get the chance to meet again, I'd love to hear all about your adventures, PlayerName...",
  ui_story_5085_50851100_40_dialog_content = "It's a shame that I can't even use alchemy to make parting gifts for everyone, but...",
  ui_story_5085_50851100_41_dialog_content = "I'll always cherish our adventure today more than any other treasure!",
  ui_story_5085_50851100_42_dialog_content = "A-As will I! It has been my pleasure to know everyone here! And Miss Barbara, I would like nothing more than to see one of your concerts someday!",
  ui_story_5085_50851100_43_dialog_content = "Oh? Then I'll make sure you get the best VIP treatment imaginable!",
  ui_story_5085_50851100_44_dialog_content = "Even though our time together was short... I'll never forget any of you.",
  ui_story_5085_50851100_45_dialog_content = "Zarya! Let's do our best and keep on growing!",
  ui_story_5085_50851100_46_dialog_content = "I-I won't forget either, but... But I won't lose to you either, Patty!",
  ui_story_5085_50851100_47_dialog_content = "I know it's time to go our separate ways, but I just can't say it out loud...",
  ui_story_5085_50851100_48_dialog_content = "Don't look so sad, PlayerName! I'm sure we'll meet again someday!",
  ui_story_5085_50851100_49_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5085_50851100_50_dialog_content = "Uh...",
  ui_story_5085_50851100_51_dialog_content = "W-We're still here?!",
  ui_story_5085_50851100_52_dialog_content = "P-Pardon the interruption, but I think I can explain!",
  ui_story_5085_50851100_53_dialog_content = "Fleur? Wait... You're not still the prince, are you?",
  ui_story_5085_50851100_54_dialog_content = "No, I'm fairly certain I'm still Fleur.",
  ui_story_5085_50851100_55_dialog_content = "\"Fairly certain\"?!",
  ui_story_5085_50851100_56_dialog_content = "That's right, although I do have a message for everyone from the prince...",
  ui_story_5085_50851100_57_dialog_content = "Thanks to your efforts, he finally learned that his precious people made it safely off the island, and started new lives on Astra's mainland.",
  ui_story_5085_50851100_58_dialog_content = "He also sincerely apologized for making so much trouble for everyone.",
  ui_story_5085_50851100_59_dialog_content = "So as a token of goodwill, he used the last remaining power of the ruins...",
  ui_story_5085_50851100_60_dialog_content = "To keep the three of you in our world for a little while longer!",
  ui_story_5085_50851100_61_dialog_content = "Unfortunately, the ruins didn't have much power left in them, and soon the effect will wear off.",
  ui_story_5085_50851100_62_dialog_content = "But at the very least, you'll be able to enjoy a nice summer adventure here on Astra!",
  ui_story_5085_50851100_63_dialog_content = "Huh?!",
  ui_story_5085_50851100_64_dialog_content = "That's great and all... But don't you think he should be apologizing to you most of all?",
  ui_story_5085_50851100_65_dialog_content = "Ah, there's no need to worry about that. He already imparted the knowledge of that mecha to me!",
  ui_story_5085_50851100_66_dialog_content = "Once we get home, I'll be able to make something truly incredible.",
  ui_story_5085_50851100_67_dialog_content = "(Wait, that means he was actually upset when we destroyed it earlier!)",
  ui_story_5085_50851100_68_dialog_content = "Anyways... I think we're missing the point here...",
  ui_story_5085_50851100_69_dialog_content = "Then... Does this mean I can stay in your world for a little while longer?!",
  ui_story_5085_50851100_70_dialog_content = "In that case, I want to see everything this world has to offer! The Colossus, the Rediesel Desert, Lumopolis... You can show us all of that and more, right Navigator?!",
  ui_story_5085_50851100_71_dialog_content = "Of course! You're our close friends now, as well as the people who saved our lives earlier.",
  ui_story_5085_50851100_72_dialog_content = "As the Navigator of the Colossus, it would be my honor to welcome the three of you aboard!",
  ui_story_5085_50851100_73_dialog_content = "Wow, thank you so much! I can't wait to go on all sorts of adventures in your world!",
  ui_story_5085_50851100_74_dialog_content = "Let's have as much fun as we can before it's actually time to say goodbye!",
  ui_story_5085_50851100_76_dialog_content = "I'm counting on you to show me around this world, Navigator! Alright, let's go!",
  ui_story_5085_50851100_77_dialog_content = "Ryza, Navigator... May I join you as well?",
  ui_story_5085_50851100_78_dialog_content = "Don't forget about me!",
  ui_story_5085_50851100_79_dialog_content = "<color=#e8d9bb>Rumble—</color>",
  ui_story_5085_50851100_80_dialog_content = "<color=#e8d9bb>The island lies silently at the bottom of the sea, along with the evidence of its former glory. Now, a new summer adventure is about to begin.</color>",
  ui_story_5085_50851100_81_dialog_content = "Next stop: Astra! Full sail ahead!"
}
return config
